function abort(g,e){if(e.id!=='player'&&e.act&&e.act.id!=='land'){if(e.act.id==='reaperIce')e.specialCD=360;else e.cdLeft=e.enr?42:range(g,...e.act.def.cd);}if(e.grabbed==='player'){const hold=g.p.act;g.p.grabbing=null;hold.grabbed=false;hold.def={total:hold.f+13,hits:[]};e.grabbed=null;}if(e.id==='player')g.buffer=null;if(e.grabbing){const t=g.enemies.find(t=>t.id===e.grabbing);if(t&&!t.dead){t.grabbed=null;t.state=t.z>0?'air':'hurt';t.stun=t.z?0:18;t.vz=0;}e.grabbing=null;}e.act=null;e.vx=0;}
