function effect(e,type,source,duration=240,value=3){const old=e.effects.find(x=>x.type===type&&x.source===source);if(old){old.left=duration;old.value=value;if(type==='shock')old.charges=Math.max(old.charges,5);return;}const same=e.effects.filter(x=>x.type===type);if(['bleed','poison'].includes(type)&&same.length>=3){const weakest=same.sort((a,b)=>a.value-b.value||a.left-b.left)[0];if(value<weakest.value||value===weakest.value&&duration<=weakest.left)return;e.effects.splice(e.effects.indexOf(weakest),1);}e.effects.push({type,source,left:duration,value,next:type==='burn'?60:30,charges:5,ready:0});}
