function validStart(g,id){const p=g.p;if(p.dead)return '死亡';if(p.effects.some(x=>x.type==='bind')&&['jump','back','escape'].includes(id))return '束缚';if(p.effects.some(x=>x.type==='silence')&&['wave','zone','ult'].includes(id))return '沉默';if(id==='escape')return isControl(p)&&!p.grabbed&&!p.protect?'':'当前不能脱身';if(id==='recover')return p.state==='down'&&p.downAge<18?'':'不在受身窗口';if(isControl(p)||['recover','guardExit','guardPrepare'].includes(p.state))return '受控';if(id==='air')return p.z>0&&p.airHits<2?'':'无法空中斩';if(p.z>0)return '必须在地面';return '';}
