 if(a.hit){if(id===d.next&&f>=d.cancel)return true;if(d.skillCancel&&f>=d.cancel&&['up','tri','wave','slam','zone','ult','grab'].includes(id))return true;if(d.to?.includes(id)&&f>=d.cancel)return true;if(id==='back'&&f>=(d.defend||d.cancel||9999))return true;if(id==='guard'&&d.guard&&f>=d.cancel)return true;if(id==='guard'&&['attack1','attack2','attack3'].includes(a.id)&&f>=(d.defend||d.cancel))return true;}
