export function retry(g,a){if(g.terminal)return {error:'副本已结束，只能回城'};if(!g.dead)return {error:'当前未死亡'};if(g.mode==='challenge'&&g.continues===0){g.terminal='failed';g.dirty=true;return {error:'续战次数用尽'};}const p=g.p;if(g.mode==='challenge')g.continues--;else{p.souls=g.roomSoul;const s=panel(a);p.atk=s.atk+p.souls*2;p.mag=s.mag+p.souls*2;p.cd={};g.seed=g.roomSeed;loadRoom(g,g.room);}p.hp=p.maxhp;p.mp=p.maxmp;p.breath=100;p.guard=100;p.dead=false;p.state='idle';p.z=0;p.vz=0;p.act=null;p.stun=0;p.down=0;p.bleed=0;p.effects=[];p.hard=null;p.hardContext=null;p.hardLeft=0;p.protect=0;p.stop=0;p.guardLock=0;p.slowTime=0;p.mark=0;p.vx=0;p.airHits=0;p.airTime=0;p.run=false;p.recover=0;p.protectionClock=0;p.protectionInv=false;p.grabbing=null;p.grabbed=null;bounds(g,p);const zones=g.zones.map(z=>z.id);for(const e of g.enemies){e.mark=0;e.effects=e.effects.filter(x=>x.type!=='slow'||!zones.includes(x.source));e.slowTime=0;if(e.grabbed==='player'){e.grabbed=null;e.state='hurt';e.stun=18;}}p.inv=g.mode==='challenge'?150:60;p.reviveInv=true;resetCombo(p);g.dead=false;g.paused=false;g.pauseReason='';g.keys={};g.input=[];g.buffer=null;g.lastTap=null;g.zones=[];g.projectiles=g.projectiles.filter(b=>b.source!=='player');g.fog=rooms.slice(0,g.room).reduce((n,r)=>n+r.width,0)-250;g.dirty=true;return {ok:true};}
export function finish(g,a){if(g.settled)return a;g.settled=true;if(g.mode!=='training'){for(const [k,n]of Object.entries(g.p.drugs))receive(a,k,n);a.active=false;a.locked=[];}return a;}
export function view(g){return {id:g.id,mode:g.mode,frame:g.frame,room:g.room,roomName:rooms[g.room].name,width:rooms[g.room].width,p:g.p,enemies:g.enemies,effects:g.effects,projectiles:g.projectiles,zones:g.zones,pickups:g.pickups,numbers:g.numbers||[],fog:g.fog-rooms.slice(0,g.room).reduce((n,r)=>n+r.width,0),paused:g.paused,pauseReason:g.pauseReason,terminal:g.terminal,dead:g.dead,continues:g.continues,hitboxes:g.attacks.map(h=>({x:h.x,y:h.y,z:h.z,face:h.face,shape:h.shape})),logs:g.logs,command:g.command,clear:g.clear};}
